import java.io.*;import java.nio.file.*;import java.util.*;
import com.android.tools.smali.dexlib2.*;import com.android.tools.smali.dexlib2.iface.*;import com.android.tools.smali.dexlib2.iface.instruction.*;import com.android.tools.smali.dexlib2.immutable.*;import com.android.tools.smali.dexlib2.builder.*;import com.android.tools.smali.dexlib2.builder.instruction.*;import com.android.tools.smali.dexlib2.writer.pool.DexPool;import com.android.tools.smali.dexlib2.writer.io.MemoryDataStore;
/** Proves opcode/offset-only differences by putting both inputs into identical jumbo-string representation. */
public class NormalizeClassDiff {
 static Map<String,ClassDef> load(String p,Set<String>types)throws Exception{Map<String,ClassDef>r=new TreeMap<>();MultiDexContainer<? extends DexFile>z=DexFileFactory.loadDexContainer(new File(p),Opcodes.forApi(26));for(String n:z.getDexEntryNames())for(ClassDef c:z.getEntry(n).getDexFile().getClasses())if(types.contains(c.getType()))r.put(c.getType(),c);return r;}
 static byte[] normalize(ClassDef c)throws Exception{List<Method>methods=new ArrayList<>();for(Method m:c.getMethods()){MethodImplementation impl=m.getImplementation();if(impl!=null){MutableMethodImplementation mut=new MutableMethodImplementation(impl);for(int i=0;i<mut.getInstructions().size();i++){Instruction ins=mut.getInstructions().get(i);if(ins.getOpcode()==Opcode.CONST_STRING)mut.replaceInstruction(i,new BuilderInstruction31c(Opcode.CONST_STRING_JUMBO,((OneRegisterInstruction)ins).getRegisterA(),((ReferenceInstruction)ins).getReference()));}impl=mut;}methods.add(new ImmutableMethod(m.getDefiningClass(),m.getName(),m.getParameters(),m.getReturnType(),m.getAccessFlags(),m.getAnnotations(),m.getHiddenApiRestrictions(),impl));}ClassDef n=new ImmutableClassDef(c.getType(),c.getAccessFlags(),c.getSuperclass(),c.getInterfaces(),c.getSourceFile(),c.getAnnotations(),c.getFields(),methods);MemoryDataStore out=new MemoryDataStore();try{DexPool.writeTo(out,new ImmutableDexFile(Opcodes.forApi(26),Collections.singleton(n)));return Arrays.copyOf(out.getBuffer(),out.getSize());}finally{out.close();}}
 static String list(Collection<String>x){List<String>r=new ArrayList<>();for(String s:x)r.add("\""+s+"\"");return "["+String.join(",",r)+"]";}
 public static void main(String[]a)throws Exception{Set<String>types=new TreeSet<>(Files.readAllLines(Path.of(a[2])));Map<String,ClassDef>x=load(a[0],types),y=load(a[1],types);List<String>same=new ArrayList<>(),changed=new ArrayList<>(),errors=new ArrayList<>();int n=0;for(String s:types){try{if(Arrays.equals(normalize(x.get(s)),normalize(y.get(s))))same.add(s);else changed.add(s);}catch(Exception e){errors.add(s);System.err.println("ERROR "+s+" "+e);}if(++n%100==0)System.err.println(n+"/"+types.size());}String report="{\"normalized_identical_count\":"+same.size()+",\"normalized_changed_count\":"+changed.size()+",\"normalized_identical_classes\":"+list(same)+",\"normalized_changed_classes\":"+list(changed)+",\"errors\":"+list(errors)+"}\n";Files.writeString(Path.of(a[3]),report);System.out.println("normalized identical="+same.size()+" changed="+changed.size()+" errors="+errors.size());for(String s:changed)System.out.println(s);}
}
